import logging
import warnings
from functools import partial
from pathlib import Path

import requests
from robot.libraries.BuiltIn import BuiltIn
from taf.internal.impact_radar import log_radar

from taf.converters.base.interface import base
from taf.converters.eventdecoder.factory import EventDecoderConverterFactory
from taf.collectors.core.entities.local_executor import LocalExecutor


logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class eventdecoder(base):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(self, **kwargs):
        self._local_executor = self._create_local_executor()
        super(eventdecoder, self).__init__(**kwargs)

    def create_eventdecoder_converter(
            self,
            name,
            input_file_path,
            output_file_path=None,
            output_file_format=None,
            tti_dec_path=None,
            conversion_filter=None,
            tti_dec_venv_path=None,
            excel_csv_options=None,
            eventdecoder_options=None,
            eventdecoder_stdout_path=None):

        """
        Create a converter to convert TTI trace pcap/bin files to json/csv format.

        Read a TTI trace \\*.pcap (streaming mode) or \\*.bin (snapshot mode) file and decode it with the tti-dec
        toolset (eventDecoder, ExcelCsvGenerator.py), that is provided for each gNB load in \\*_tti-dec.deb

        :param str name:
            name of the converter
        :param str input_file_path:
            input file path
        :param Optional[str] output_file_path:
            output file path, default is "output"
        :param Optional[str] output_file_format:
            output file format can be "json", "legacyCsv" or "excelCsv", default is "legacyCsv"
        :param Optional[str] tti_dec_path:
            path where tti-dec is installed, default is "/opt/tti-dec/tti-dec-bin"
        :param Optional[Union[Callable[[dict],bool],str]] conversion_filter: filter for TTI events (for json or excelCsv):

            - regular expression to be matched with the TTI event type or
            - callable which checks for a TTI event (dict) whether it shall be kept or
            - name of a Robot keyword which checks for a TTI event (dict) whether it shall be kept

            default is no filtering. Recommendation: Use a callable (see example test case
            **"library keyword filter SFN, JSON"** below) to avoid a huge log.html due to logging of calls of the
            filter keyword.
        :param Optional[str] tti_dec_venv_path:
            path of virtualenv to be used for tti-dec Python scripts, default is "/opt/tti-dec/venv"
        :param Optional[str] excel_csv_options:
            options for ExcelCsvGenerator.py script (e. g. "-d combineDlAndUl -s 100"),
            if output_file_format is "excelCsv", default is ""
        :param eventdecoder_options: additional options for the eventdecoder call, e. g. "--split 2000000"
        :param Optional[str] eventdecoder_stdout_path: path to store the eventdecoder stdout, default is None,
            which means that the stdout is not stored

        """

        warnings.warn(
            "TTI-DEC 1.0 will not be available from 27R2. "
            "Please use taf.converters.twdecoder for converting pcap to parquet format.",
            FutureWarning,
            stacklevel=2
        )
        log_radar("Tracking the usage of taf.converters.eventdecoder")

        logger.info("Creating Converter with alias name " + name)
        configuration = {"input_file_path": input_file_path}
        for parameter_name, parameter_value in locals().items():
            if parameter_name in [
                    "output_file_path",
                    "output_file_format",
                    "tti_dec_path",
                    "tti_dec_venv_path",
                    "excel_csv_options",
                    "eventdecoder_options",
                    "eventdecoder_stdout_path"]:
                if parameter_value is not None:
                    configuration[parameter_name] = parameter_value
            if parameter_name == "conversion_filter" and parameter_value is not None:
                configuration[parameter_name] = self._get_filter_robot(parameter_value)

        converter = EventDecoderConverterFactory().create(
            configuration=configuration,
            existing_arguments={})
        logger.info(name + " converter created successfully")
        self.set_alias(name, converter)

    def _get_filter_robot(self, conversion_filter):
        try:
            builtin = self._create_builtin()
            builtin.keyword_should_exist(conversion_filter)
            filter_func = partial(builtin.run_keyword, conversion_filter)
        except AssertionError as err:
            logger.info(err)
            filter_func = conversion_filter
        return filter_func

    def _create_builtin(self):
        return BuiltIn()

    def install_airphone_decoder(
            self,
            version,
            install_path="/opt/airphone-tti-dec",
            base_url="https://hzisoj70.china.nsn-net.net/artifactory/mnp5g-airphone-ci-gen-local/Airphone",
            token=None):

        """
        TTI trace decoders for AirPhone (airphone-ttiTraceDecoder_*.tar.gz)

        :param str version:
            current AirPhone version, e. g. /ffs/run/TargetBD_5G_AP_0004_000000_018373.xml -> 4.0.18373
        :param Optional[str] install_path:
            path to install the decoder, default is /opt/airphone-tti-dec
        :param Optional[str] base_url:
            base url to retrieve airphone tti-dec, default is
            `<https://hzisoj70.china.nsn-net.net/artifactory/mnp5g-airphone-ci-gen-local/Airphone>`_
        :param Optional[str] token: user token for authentication, default is the content of /etc/token/ca_ute_artifactory_readonly

        .. code-block:: robotframework

            *** Settings ***
            Library      taf.converters.eventdecoder

            *** Test Cases ***
            simple case, Airphone
                install_airphone_decoder
                ...         version=4.0.17008
                ...         install_path=/opt/airphone-tti-dec

            user provided token for authentication
                install_airphone_decoder
                ...         version=4.0.17008
                ...         install_path=/opt/airphone-tti-dec
                ...         token=mytoken
        """

        url = f'{base_url}/{version}/airphone-ttiTraceDecoder_static_{version}.tar.gz'
        logger.info(f"Getting airphone ttitrace_decoder from {url}")

        self._retrieve_url(url, "/tmp/airphone-ttitrace.tar.gz", token)
        sudo_prefix = self._local_executor.sudo_prefix()

        self._local_executor.execute(f'{sudo_prefix}mkdir -p "{install_path}"')

        extract_command = f'{sudo_prefix}tar -xvf /tmp/airphone-ttitrace.tar.gz -C "{install_path}"'
        self._local_executor.execute(extract_command)
        self._local_executor.execute(f'{sudo_prefix}chown -R $(id -u):$(id -g) "{install_path}"')

        self._local_executor.execute("rm -f /tmp/airphone-ttitrace.tar.gz")

        logger.info("Airphone ttitrace version %s installed successfully" % version)

    def _create_local_executor(self):
        return LocalExecutor()

    def _retrieve_url(self, url, filename, token):
        token_to_use = token if token else self._get_default_token().decode()
        headers = {'Authorization': f'Bearer {token_to_use}'}

        response = requests.get(url, headers=headers)
        response.raise_for_status()

        self._write_file(filename, response.content)

    def _get_default_token(self):
        return self._read_file('/etc/token/ca_ute_artifactory_readonly').strip()

    def _read_file(self, file_path):
        return Path(file_path).read_bytes()

    def _write_file(self, file_path, content):
        Path(file_path).write_bytes(content)
